cd /work/packages/zod && cat > /tmp/chk.test.ts <<'EOF'
import { check } from "recheck";
import { test } from "vitest";
import * as r from "/work/packages/zod/src/v4/core/regexes.js";
test("x", async () => {
  const list: [string, RegExp][] = [];
  for (const [k, v] of Object.entries(r)) if (v instanceof RegExp) list.push([k, v]);
  list.push(["emoji", r.emoji()], ["mac", r.mac()], ["mac-", r.mac("-")], ["uuid", r.uuid()]);
  for (let i = 1; i <= 8; i++) list.push(["uuid" + i, r.uuid(i)]);
  list.push(["string", r.string()], ["string2", r.string({ minimum: 1, maximum: 5 })]);
  for (const p of [null, -1, 0, 3, 6] as any[]) {
    list.push(["time" + p, r.time({ precision: p })]);
    for (const local of [true, false]) for (const offset of [true, false])
      list.push([`dt${p}${local}${offset}`, r.datetime({ precision: p, local, offset })]);
  }
  const bad: string[] = [];
  for (const [k, v] of list) { const res = await check(v.source, v.flags); if (res.status !== "safe") bad.push(k + " " + res.status); }
  console.log("BAD", bad);
});
EOF
cp /tmp/chk.test.ts src/v4/classic/tests/zz.test.ts && cd /work && pnpm vitest run packages/zod/src/v4/classic/tests/zz.test.ts 2>&1 | grep -E "BAD|passed|failed|Error" ; rm packages/zod/src/v4/classic/tests/zz.test.ts

